# ⭐⭐ La taille des chiffres dans les bulles. MESURÉE, PAS CALCULÉE :
#    voir la note de livraison.
_T_BULLE = 30.0
# ⚠️⚠️ 30 pt EST LE MAXIMUM, ET IL A ÉTÉ MESURÉ, PAS CALCULÉ.
#    On a imprimé à 500 dpi CHAQUE valeur de CHAQUE plage, dans SA bulle,
#    avec le gras du contour, et compté les pixels où le chiffre touche
#    un trait de RANIHEI :
#       30 pt → aucun contact
#       31 pt → 1 pixel sur le « 14 » de la 1re bulle (la plus petite)
#       32 pt → 44 px répartis sur quatre bulles
# ⚠️ NE PAS MONTER SANS REFAIRE CETTE MESURE.
_GARDE = 1.15
# ⚠️⚠️ CE FACTEUR N'EST PAS UNE MARGE, C'EST UN ÉTALONNAGE : réglé pour
#    laisser passer exactement les 30 pt validés sur le carton
#    d'aujourd'hui, et pas un point de plus.

# Le retrait du cadre de microtexte. MESURÉ sur sept valeurs :
#    0,4 mm -> 3 px   0,8 -> 10   1,0 -> 16   1,2 -> 35
#    1,6 mm -> 44     2,0 -> 30   3,0 -> 123
# Les retraits courts seraient plus propres mais collent au trait de
# coupe : un massicot de travers emporterait le microtexte, donc la
# protection anti-photocopie. 1,2 mm est le retrait de tous ses autres
# jeux, et 35 pixels a 500 dpi (un pixel = 0,05 mm) ne se voient pas.
_RETRAIT = 1.2 * mm

# La pastille « Série : » : à la place EXACTE des « 001 » effacés.
#   SERIE_GAUCHE : le bord gauche des chiffres, juste après les deux points
#   SERIE_BASE   : leur ligne de pied
#   SERIE_PT     : leur hauteur d'origine convertie en corps de police
#   SERIE_LARG   : la place libre jusqu'au cadre arrondi, en fraction de
#                  la largeur du carton — six chiffres au lieu de trois.
# ⚠️ SA PLANCHE A DEUX CADRES DE NUMÉRO, un en haut à droite
#    (« Série : 001 ») et un en bas à droite (« 0001 »). Les DEUX
#    reçoivent le MÊME numéro de série : c'est le même carton.
SERIE_HAUT_X = 937.5      # bord gauche, juste après « Série : »
SERIE_HAUT_BASE = 100.9
SERIE_HAUT_PT = 67.9
SERIE_HAUT_LARG = 0.047
SERIE_BAS_X = 940.2       # milieu du cadre du bas (texte centré)
