def _tracer_decor(c, larg, haut):
    """Repose le dessin de RANIHEI dans un rectangle larg x haut.
    ⚠️ UN SEUL remplissage pair-impair pour tous les contours : les blancs
    à l'intérieur des formes (l'œil du dragon, le creux d'une bulle, une
    écaille) se creusent tout seuls. Contour par contour, la feuille
    serait des centaines de fois plus lourde."""
    p = c.beginPath()
    for contour in _DECOR.split("|"):
        for t in contour.split(" "):
            v = [float(z) for z in t[1:].split(",")]
            xs = [v[i] / 1000.0 * larg for i in range(0, len(v), 2)]
            ys = [haut - v[i] / 1000.0 * haut for i in range(1, len(v), 2)]
            if t[0] == "M":
                p.moveTo(xs[0], ys[0])
            elif t[0] == "L":
                p.lineTo(xs[0], ys[0])
            else:
                p.curveTo(xs[0], ys[0], xs[1], ys[1], xs[2], ys[2])
        p.close()
    c.drawPath(p, stroke=0, fill=1)


def _forme_decor(c):
    """Gravé UNE SEULE FOIS par document, puis chaque carton s'y réfère.

    ⚠️⚠️ LA FORME NE FIXE AUCUNE COULEUR, ET C'EST VOULU. Un tampon PDF
    qui ne choisit pas sa couleur prend celle posée au moment où on
    l'utilise : on grave donc UN tampon pour les dix couleurs de
    l'arc-en-ciel, au lieu de dix.
    ⚠️ NE PAS REMETTRE setFillColor ICI : la couleur se pose AVANT le
    doForm, dans _dessiner_carte."""
    nom = "AREAREA_DECOR"
    if not getattr(c, "_area_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CARD_W, uppery=CARD_H)
        _tracer_decor(c, CARD_W, CARD_H)
        c.endForm()
        c._area_forme_faite = True
    return nom


# ══ LA FEUILLE ═══════════════════════════════════════════════════════
# 6 cartons par feuille A4 PAYSAGE, en 2 colonnes et 3 rangées — la
# planche que RANIHEI a fournie. Son carton est très allongé (2,30 fois
# plus large que haut) : en portrait il n'en tiendrait que 3 par feuille.
PAGE_W, PAGE_H = landscape(A4)          # 297 × 210 mm
COLS_PAGE = 2
ROWS_PAGE = 3
MARGIN_X = 8 * mm
GUTTER_X = 5 * mm
GUTTER_Y = 4 * mm
CARD_W = (PAGE_W - 2 * MARGIN_X - GUTTER_X) / COLS_PAGE
CARD_H = CARD_W * MAQ_H / MAQ_W          # le carton garde le format de la maquette
BLOC_H = ROWS_PAGE * CARD_H + (ROWS_PAGE - 1) * GUTTER_Y
MARGIN_BOT = (PAGE_H - BLOC_H) / 2       # le bloc est centré sur la hauteur

RAINBOW = [
    "#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
    "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41",
]
GRIS = colors.Color(0.42, 0.42, 0.42)
GRIS_CLAIR = colors.Color(0.80, 0.80, 0.80)


def _gen_carte(rng):
    """Cinq numéros, UN PAR LETTRE du mot BINGO, dans l'ordre des bulles.
    Deux bulles ne peuvent JAMAIS porter le même numéro : les plages ne
    se chevauchent pas."""
    return [rng.randint(a, b) for a, b in PLAGES]


def _dessiner_carte(c, x0, y0, nums, couleur_hex, serie, style="eco",
                    evenement_id=""):
    police_ch, gris_ch = _style_chiffres(style)

    # 1) LE DESSIN DE RANIHEI, tel quel.
    #    La couleur se pose ICI, juste avant de reposer le tampon : c'est
    #    ce qui permet de n'en graver qu'un seul pour toutes les couleurs.
    _nom_forme = _forme_decor(c)
    c.saveState()
    col = colors.HexColor(couleur_hex)
    c.setFillColor(col)
    c.setStrokeColor(col)
    c.translate(x0, y0)
    c.doForm(_nom_forme)
    c.restoreState()

    if _sec:   # cadre intérieur en microtexte (anti-photocopie)
        try:
            _sec.cadre_micro(c, x0, y0, CARD_W, CARD_H, serie, retrait=_RETRAIT)
        except Exception:
            pass

    # 2) LES CINQ NUMÉROS DANS LES BULLES — la seule chose qu'on ajoute.
    for (px, py, pr), (pa, pb), val in zip(BULLES, PLAGES, nums):
        cx = x0 + px / 1000.0 * CARD_W
        cy = y0 + CARD_H - py / 1000.0 * CARD_H
        r = pr / 1000.0 * CARD_W
        t = _T_BULLE
        # ⚠️ GARDE-FOU, à ne pas retirer : si le carton rapetisse un jour
        #    (autre mise en page, autre format de papier), le chiffre
        #    redescend tout seul. Mieux vaut un chiffre plus petit qu'un
        #    chiffre qui mord le dessin de RANIHEI.
        # ⚠️ ON MESURE LA VALEUR LA PLUS LARGE DE **CETTE** PLAGE.
        _large = max(range(pa, pb + 1),
                     key=lambda v: pdfmetrics.stringWidth(str(v), police_ch, 20))
        while t > 4:
            lg = pdfmetrics.stringWidth(str(_large), police_ch, t)
            ht = t * 0.72
            if ((lg / 2) ** 2 + (ht / 2) ** 2) ** 0.5 <= r * _GARDE:
                break
            t -= 0.5
        if _sec:
            _sec.chiffre_micro(c, val, cx, cy - t * 0.36, t, gris_ch, police_ch,
                               epaisseur=_GRAS_TRAIT)
        else:
            c.setFillColor(gris_ch)
            c.setFont(police_ch, t)
            c.drawCentredString(cx, cy - t * 0.36, str(val))

    # 3) LE NUMÉRO DE SÉRIE, à la place des « 001 » de la maquette
    c.setFillColor(colors.HexColor(couleur_hex))
    _txt = "%06d" % serie
    # ⚠️ chaque numéro se rétrécit s'il le faut : six chiffres sont plus
    #    larges que les trois ou quatre du modèle, et ils ne doivent
    #    déborder ni de l'un ni de l'autre cadre.
    # ── le cadre du HAUT (« Série : ») — texte calé à gauche
    ts = SERIE_HAUT_PT / 1000.0 * CARD_H
    _larg = CARD_W * SERIE_HAUT_LARG
    while ts > 2.5 and pdfmetrics.stringWidth(_txt, POLICE, ts) > _larg:
        ts -= 0.25
    c.setFont(POLICE, ts)
    c.drawString(x0 + SERIE_HAUT_X / 1000.0 * CARD_W,
                 y0 + CARD_H - SERIE_HAUT_BASE / 1000.0 * CARD_H, _txt)
    # ── le cadre du BAS — texte centré
    ts = SERIE_BAS_PT / 1000.0 * CARD_H
    _larg = CARD_W * SERIE_BAS_LARG
    while ts > 2.5 and pdfmetrics.stringWidth(_txt, POLICE, ts) > _larg:
        ts -= 0.25
    c.setFont(POLICE, ts)
    c.drawCentredString(x0 + SERIE_BAS_X / 1000.0 * CARD_W,
                        y0 + CARD_H - SERIE_BAS_BASE / 1000.0 * CARD_H, _txt)

    if _sec and evenement_id:
        try:
            _sec.carton_qr(c, x0 + CARD_W * 0.86, y0 + CARD_H * 0.06,
                           CARD_H * 0.20, evenement_id, serie)
        except Exception:
            pass


def generer_pdf(nb_cartes=6, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", page_start=1):
    """⚠️ RETOURNE UN BytesIO, PAS DES OCTETS. Toute la maison est faite
    ainsi et app.py appelle .read() dessus. Un `return buf.read()` ici et
    le jeu ne fabriquerait plus rien."""
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    par_page = COLS_PAGE * ROWS_PAGE
    nb_pages = (nb_cartes + par_page - 1) // par_page

    rng = random.Random(950000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    faites = 0

    for _ in range(nb_pages):
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.0)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 3.4 * mm, "%03d" % no_page)

        for rang in range(ROWS_PAGE):
            for col_i in range(COLS_PAGE):
                if faites >= nb_cartes:
                    break
                x0 = MARGIN_X + col_i * (CARD_W + GUTTER_X)
                y0 = MARGIN_BOT + (ROWS_PAGE - 1 - rang) * (CARD_H + GUTTER_Y)
                nums = _gen_carte(rng)
                coul = (couleur_perso if (couleur and couleur_perso)
                        else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur
                        else "#4A4A4A")
                _dessiner_carte(c, x0, y0, nums, coul, serie,
                                style=style, evenement_id=evenement_id)
                serie += 1
                faites += 1

        # traits de découpe pointillés, comme sur sa planche
        c.setStrokeColor(GRIS_CLAIR); c.setLineWidth(0.4); c.setDash(3, 3)
        xm = MARGIN_X + CARD_W + GUTTER_X / 2
        c.line(xm, MARGIN_BOT - 2 * mm, xm, MARGIN_BOT + BLOC_H + 2 * mm)
        for rang in range(1, ROWS_PAGE):
            ym = MARGIN_BOT + rang * (CARD_H + GUTTER_Y) - GUTTER_Y / 2
            c.line(MARGIN_X - 2 * mm, ym, PAGE_W - MARGIN_X + 2 * mm, ym)
        c.setDash()

        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf


def generer_couleur(**kw):
    kw["couleur"] = True
    return generer_pdf(**kw)


def generer_nb(**kw):
    kw["couleur"] = False
    return generer_pdf(**kw)
